import { useGet, useLoaderContextValue } from '@pasarpolis/common-react-hooks'
import { Col, Spin } from 'antd'
import moment from 'moment-timezone'
import { useEffect } from 'react'
import { useHistory, useParams } from 'react-router'
import EbEmptyPage from '../../../../../../components/EbEmptyPage/ebEmptypage'
import { RowWithMargin } from '../../../CommonComponents'
import { bcPostDetailApis } from '../apiConfig'
import { PostStyleWrapper } from './index.style'

const BroadcastPostDetailContainer = () => {
  const history = useHistory()
  const params = useParams()
  const [postDetail, postDetailRequest] = useGet(bcPostDetailApis.postDetail)
  const [{ POST_DETAIL_LOADER }] = useLoaderContextValue()

  const data = postDetail || {}

  useEffect(() => {
    postDetailRequest({ id: params.postId })
  }, [postDetailRequest, params])

  return (
    <EbEmptyPage history={history} path='/employee-benefits/broadcast-center'>
      <Spin spinning={!!POST_DETAIL_LOADER}>
        <PostStyleWrapper>
          <RowWithMargin>
            <Col span={4}><strong>Title:</strong></Col>
            <Col span={10}>{data?.subject}</Col>
          </RowWithMargin>
          <RowWithMargin>
            <Col span={4}><strong>Content:</strong></Col>
            <Col span={10}>{data?.body}</Col>
          </RowWithMargin>
          <RowWithMargin>
            <Col span={4}><strong>Upload Image:</strong></Col>
            <Col span={10}>
              {
                  data?.image_url && (
                    <img
                      className='post-img'
                      src={data.image_url}
                      alt='Post'
                    />
                  )
                }
            </Col>
          </RowWithMargin>
          <RowWithMargin>
            <Col span={4}><strong>Recipients:</strong></Col>
            <Col span={10}>{data?.recipients?.map(({ name }) => name)?.join(', ') || 'All'}</Col>
          </RowWithMargin>
          <RowWithMargin>
            <Col span={4}><strong>Publish Date:</strong></Col>
            <Col span={10}>{moment(new Date(data?.publish_at)).format('DD-MM-YYYY HH:mm')}</Col>
          </RowWithMargin>
        </PostStyleWrapper>

      </Spin>
    </EbEmptyPage>
  )
}
export default BroadcastPostDetailContainer
